def _pause_on_error() -> None:
    if sys.stdin is not None and sys.stdin.isatty():
        try:
            input("\nPress Enter to close...")
        except (EOFError, KeyboardInterrupt):
            pass


def _check_dependencies(base_dir: Path) -> None:
    missing = [package for module, package in DEPENDENCIES if importlib.util.find_spec(module) is None]
    problems = []
    for package, required in REQUIRED_VERSIONS.items():
        try:
            installed = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            installed = None
        if installed != required or package in missing:
            problems.append(f"{package}: {installed or 'not installed'} (required {required})")
    if not problems:
        return
    requirements = base_dir / "requirements.txt"
    print(f"{APP_NAME} needs the following dependency updates:")
    print("\n".join("  " + problem for problem in problems))
    print("\nIn PowerShell, install into this same Python with:")
    executable = str(sys.executable).replace("'", "''")
    requirements_path = str(requirements).replace("'", "''")
    print(f"  & '{executable}' -m pip install --upgrade -r '{requirements_path}'")
    print("\nPackages installed under another Python version are not shared automatically.")
    _pause_on_error()
    raise SystemExit(2)


def _install_runtime(runtime_dir: Path) -> None:
    version_file = runtime_dir / ".release_version"
    current = version_file.read_text(encoding="utf-8").strip() if version_file.exists() else ""
    complete = all((runtime_dir / relative).is_file() for relative in MANAGED_FILES)
    if current == RELEASE_VERSION and complete:
        return

    runtime_dir.mkdir(parents=True, exist_ok=True)
    archive_bytes = base64.b85decode(PAYLOAD_B85)
    with zipfile.ZipFile(io.BytesIO(archive_bytes), "r") as archive:
        expected = set(MANAGED_FILES)
        received = set(archive.namelist())
        if received != expected:
            raise RuntimeError("The embedded application payload is incomplete.")
        for relative in MANAGED_FILES:
            destination = (runtime_dir / relative).resolve()
            if runtime_dir.resolve() not in destination.parents:
                raise RuntimeError("Unsafe embedded application path detected.")
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(destination.name + ".new")
            temporary.write_bytes(archive.read(relative))
            os.replace(temporary, destination)
    version_file.write_text(RELEASE_VERSION + "\n", encoding="utf-8")


def _prepare_data(data_dir: Path) -> None:
    data_dir.mkdir(parents=True, exist_ok=True)
    for folder in DATA_FOLDERS:
        (data_dir / folder).mkdir(parents=True, exist_ok=True)


def main() -> None:
    base_dir = Path(__file__).resolve().parent
    runtime_dir = base_dir / "News_Classification_Automation_Runtime"
    data_dir = base_dir / "News_Classification_Automation_Data"

    print(f"Starting {APP_NAME}...")
    print(f"Python {sys.version.split()[0]}: {sys.executable}")
    if sys.maxsize <= 2**32:
        print("This application requires 64-bit Python. Use a 64-bit Python 3.12 or 3.14 installation.")
        _pause_on_error()
        raise SystemExit(2)
    _check_dependencies(base_dir)
    _install_runtime(runtime_dir)
    _prepare_data(data_dir)

    os.environ["NEWS_CLASSIFICATION_DATA_DIR"] = str(data_dir)
    os.chdir(runtime_dir)
    sys.path.insert(0, str(runtime_dir))
    runpy.run_path(str(runtime_dir / "app.py"), run_name="__main__")


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        raise
    except KeyboardInterrupt:
        print("\nApplication stopped.")
    except Exception:
        print(f"\n{APP_NAME} could not start.\n")
        traceback.print_exc()
        _pause_on_error()
        raise SystemExit(1)
